// CR-2 — the rules reading_position stands on (docs/CONTINUE-READING.md §2). Generated by
// scripts/continue-reading/write-rules.mjs from app/lib/continueReading/schema.js.
//
//   npm run test:rules   (emulator; invented ids only)
//
// `now` in the rules is the emulator's clock, so a timestamp is written as serverTimestamp() and a
// client number is refused.
import { test, before, after, beforeEach, describe } from 'node:test';
import { serverTimestamp } from 'firebase/database';
import { makeEnv, seed, assertFails, assertSucceeds, OWNER, STRANGER, FOUNDER_A } from './helpers.mjs';

let env, owner, stranger, founder, anon;
before(async () => {
  env = await makeEnv();
  owner = env.authenticatedContext(OWNER).database();
  stranger = env.authenticatedContext(STRANGER).database();
  founder = env.authenticatedContext(FOUNDER_A).database();
  anon = env.unauthenticatedContext().database();
});
after(async () => { await env?.cleanup(); });
beforeEach(async () => {
  await env.clearDatabase();
  await seed(env, {
    'cms_stories_index/a-tale': { title: 'A tale', published: true },
    'cms_stories_index/another-tale': { title: 'Another', published: true },
    'series_instalments/bp-i1': { seriesId: 'bp', ordinal: 1, status: 'published' },
  });
});

const P = `reading_position/${OWNER}`;
const pos = (fraction = 0.4) => ({ fraction, updatedAt: serverTimestamp() });

describe('reading_position/{uid} — owner only', () => {
  test('the owner reads and writes their own; nobody else reads or writes it, founders included', async () => {
    await assertSucceeds(owner.ref(`${P}/stories/a-tale`).set(pos()));
    await assertSucceeds(owner.ref(P).get());
    await assertSucceeds(owner.ref(`${P}/stories/a-tale`).get());
    await assertFails(stranger.ref(P).get());
    await assertFails(stranger.ref(`${P}/stories/a-tale`).get());
    await assertFails(anon.ref(P).get());
    await assertFails(founder.ref(P).get());
    await assertFails(owner.ref('reading_position').get());
    await assertFails(stranger.ref(`${P}/stories/a-tale`).set(pos()));
    await assertFails(stranger.ref(`${P}/stories/a-tale`).remove());
    await assertFails(anon.ref(`${P}/stories/a-tale`).set(pos()));
    await assertFails(founder.ref(`${P}/stories/a-tale`).set(pos()));
  });
  test('the owner removes a record (the end-of-story marker), even one whose story has left the index', async () => {
    await assertSucceeds(owner.ref(`${P}/stories/a-tale`).set(pos()));
    await env.withSecurityRulesDisabled((ctx) => ctx.database().ref('cms_stories_index/a-tale').remove());
    await assertSucceeds(owner.ref(`${P}/stories/a-tale`).remove());
  });
});

describe('reading_position/{uid}/stories/{slug} — the shape', () => {
  test('fraction 0 to 1, a number', async () => {
    await assertSucceeds(owner.ref(`${P}/stories/a-tale`).set(pos(0)));
    await assertSucceeds(owner.ref(`${P}/stories/a-tale`).set(pos(1)));
    await assertSucceeds(owner.ref(`${P}/stories/a-tale`).set(pos(0.5)));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set(pos(-0.01)));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set(pos(1.01)));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set(pos('0.5')));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set({ updatedAt: serverTimestamp() }));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set({ fraction: 0.5 }));
  });
  test('updatedAt is the server\'s now, never a client number', async () => {
    await assertFails(owner.ref(`${P}/stories/a-tale`).set({ fraction: 0.5, updatedAt: Date.now() }));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set({ fraction: 0.5, updatedAt: Date.now() + 86400000 }));
    await assertFails(owner.ref(`${P}/stories/a-tale/updatedAt`).set(1));
  });
  test('no other field', async () => {
    await assertFails(owner.ref(`${P}/stories/a-tale`).set({ ...pos(), cfi: 'x' }));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set({ ...pos(), title: 'A tale' }));
  });
  test('the slug must match ids.js and exist in cms_stories_index', async () => {
    await assertFails(owner.ref(`${P}/stories/not-in-the-index`).set(pos()));
    await assertFails(owner.ref(`${P}/stories/A-Tale`).set(pos()));
    await assertFails(owner.ref(`${P}/stories/a_tale`).set(pos()));
    await assertFails(owner.ref(`${P}/stories/a--tale`).set(pos()));
    await seed(env, { [`cms_stories_index/${'a'.repeat(129)}`]: { title: 'long' } });
    await assertFails(owner.ref(`${P}/stories/${'a'.repeat(129)}`).set(pos()));
    await assertSucceeds(owner.ref(`${P}/stories/another-tale`).set(pos()));
  });
});

describe('reading_position/{uid}/hidden — the ✕', () => {
  test('a story or an instalment, hidden at the server\'s now', async () => {
    await assertSucceeds(owner.ref(`${P}/hidden/stories/a-tale`).set(serverTimestamp()));
    await assertSucceeds(owner.ref(`${P}/hidden/instalments/bp-i1`).set(serverTimestamp()));
    await assertFails(owner.ref(`${P}/hidden/stories/a-tale`).set(Date.now()));
    await assertFails(owner.ref(`${P}/hidden/instalments/bp-i1`).set(true));
    await assertFails(stranger.ref(`${P}/hidden/stories/a-tale`).set(serverTimestamp()));
  });
  test('unknown slugs and instalment ids are refused', async () => {
    await assertFails(owner.ref(`${P}/hidden/stories/no-such-tale`).set(serverTimestamp()));
    await assertFails(owner.ref(`${P}/hidden/instalments/bp-i9`).set(serverTimestamp()));
    await assertFails(owner.ref(`${P}/hidden/instalments/bp~i1`).set(serverTimestamp()));
  });
  test('the owner may take a hide back', async () => {
    await assertSucceeds(owner.ref(`${P}/hidden/stories/a-tale`).set(serverTimestamp()));
    await assertSucceeds(owner.ref(`${P}/hidden/stories/a-tale`).remove());
  });
});

describe('$other is false at every level', () => {
  test('under the uid, under hidden, and inside a record', async () => {
    await assertFails(owner.ref(`${P}/instalments/bp-i1`).set(pos()));
    await assertFails(owner.ref(`${P}/notes`).set('x'));
    await assertFails(owner.ref(`${P}/hidden/series/bp`).set(serverTimestamp()));
    await assertFails(owner.ref(`${P}/stories/a-tale`).set({ ...pos(), extra: 1 }));
    await assertFails(owner.ref(P).set({ stories: { 'a-tale': pos() }, extra: true }));
    await assertSucceeds(owner.ref(P).set({ stories: { 'a-tale': pos() }, hidden: { stories: { 'another-tale': serverTimestamp() } } }));
  });
});
